 body+='<h2 id="sources">Sources and scope</h2>'+p('Primary references below support the stated definitions or framework. The worked case, numbers and decision records are original MyBreakeven material. Reviewed November 7, 2026; no external professional sign-off is claimed.')+'<ul>'+''.join('<li><a href="'+u+'">'+label+'</a></li>' for u,label in sources)+'</ul>'
 post=dict(id=id,slug=slug,title=title,seoTitle=seo,description=desc,metaDescription=desc,primaryKeyword=keyword,scopeBoundary=boundary,opening=opening,tag='Break-Even Concepts',tags=['Business finance','Worked example','Practical worksheet'],cluster='concepts',published='2026-11-07',modified='2026-11-07',editorialStatus='published',image='/images/title-covers/day4-'+slug+'-20261107.webp',alt=alt,imageCaption='AI-created topic illustration. Numerical examples and diagrams are original fictional teaching cases.',html=body,sectionLinks=[[s,h]for s,h,_ in sections]+[['worksheet','Worksheet'],['sources','Sources']],faq=[dict(q=q,a=a)for q,a in faq])
 posts.append(post)
 fields='<div class="fields">'+''.join('<label>'+x+'<input aria-label="'+x+'"></label>' for x in ['Business / preparer','Reporting date or horizon','Currency / accounting basis','Evidence references','Reviewer / next review date'])+'</div>'
 blanktable=table('Your working record — replace each cell',blank,[['Enter record '+str(i)]+['Enter value']*(len(blank)-1)for i in range(1,6)]).replace('<td>','<td contenteditable="true">').replace('<th scope="row">','<th scope="row" contenteditable="true">')
 sheet='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+' — Worksheet</title><style>body{font:16px/1.55 system-ui;color:#18233b;max-width:1050px;margin:32px auto;padding:0 20px}h1{font-size:30px;line-height:1.2}h2{margin-top:32px;color:#4935a8}.article-table-scroll{overflow-x:auto}table{border-collapse:collapse;width:100%;min-width:550px}td,th{padding:12px;border:1px solid #aab3c9;text-align:left}caption{text-align:left;font-weight:bold;padding:10px 0}thead{background:#eeeafd}input,textarea{font:inherit;padding:10px;border:1px solid #8490a7;border-radius:4px;box-sizing:border-box;width:100%}label{display:block;margin:12px 0}.fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px}button{font:inherit;background:#4935a8;color:white;border:0;padding:12px 18px;border-radius:6px}td:focus,th:focus{outline:3px solid #745bd7}@media print{button{display:none}.article-table-scroll{overflow:visible}table{min-width:0;font-size:10px}tr{break-inside:avoid}body{margin:0;max-width:none}textarea{min-height:70px}}</style><body><p>MYBREAKEVEN • Published November 7, 2026</p><h1>'+title+' — working record</h1><p>Original fictional USD case. This worksheet does not automatically calculate. Edit the blank cells, then print or save your completed copy before closing. Fields are not uploaded or saved by this page.</p><button onclick="window.print()">Print / save PDF</button><h2>Completed teaching case</h2>'+table('Reconciled case from the guide',headers,rows)+'<h2>Your evidence and assumptions</h2>'+fields+blanktable+'<label>Reconciliation / independent calculation<textarea rows="4"></textarea></label><label>Unresolved issue, action owner, deadline and stop / escalation condition<textarea rows="4"></textarea></label><p>Check amounts, dates, scope and source documents independently. Planning education; not accounting, legal, tax or lending advice.</p><a href="https://mybreakeven.com/blogs/'+slug+'/">Read the full method and limitations</a></body></html>'
